#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

# gh.exe 的位置：winget / 官方 MSI 装到 Program Files；也兜底查 PATH。
# 注意当前窗口的 PATH 是启动时的快照，刚装好的 gh 在这个窗口里看不到，
# 所以下面一律优先用绝对路径调用。
find_gh() {
  local c
  for c in "/c/Program Files/GitHub CLI/gh.exe" \
           "/c/Program Files (x86)/GitHub CLI/gh.exe" \
           "$HOME/AppData/Local/Programs/GitHub CLI/gh.exe"; do
    if [[ -x "$c" ]]; then printf '%s' "$c"; return 0; fi
  done
  c=$(command -v gh.exe 2>/dev/null || true)
  if [[ -n "$c" ]]; then printf '%s' "$c"; return 0; fi
  return 1
}

# 读 Windows 的「系统代理」（WinINET / IE 设置）。gh 是 Go 程序，**不读**这个设置，
# 只认 HTTP_PROXY / HTTPS_PROXY 环境变量；不补上就会直连 github.com 然后超时，
# 表现就是「看不到一次性代码」——因为 device code 那一步根本没发出去。
# 输出形如 "1|127.0.0.1:7897"（ProxyEnable|ProxyServer），失败时不输出。
system_proxy() {
  command -v powershell.exe >/dev/null 2>&1 || return 1
  local v
  v=$(powershell.exe -NoProfile -NonInteractive -Command \
    "\$s=Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings'; \"\$(\$s.ProxyEnable)|\$(\$s.ProxyServer)\"" \
    2>/dev/null | tr -d '\r\n')
  [[ -n "$v" ]] || return 1
  printf '%s' "$v"
}

banner "GitHub CLI (gh) 安装向导"

GH_EXE=$(find_gh || true)

# ── 1/5 装 gh ─────────────────────────────────────────────────────────────
stage "安装 GitHub CLI"
say "目标：在这台 Windows 上装官方 GitHub CLI（官网 https://cli.github.com/）。"
note "本向导不采集任何密钥：登录凭据由 gh 自己写进 Windows 凭据管理器。"

DO_INSTALL=0
if [[ -n "$GH_EXE" ]]; then
  say "检测到已经装过 gh：$GH_EXE"
  "$GH_EXE" --version || true
  if confirm "还想用 winget 覆盖安装 / 升级到最新版吗？"; then
    DO_INSTALL=1
  else
    note "跳过安装，直接用现有的 gh 往下走。"
  fi
else
  DO_INSTALL=1
fi

if [[ "$DO_INSTALL" == "1" ]]; then
  if command -v winget.exe >/dev/null 2>&1; then
    say "用 winget 装 GitHub.cli（官方 wix MSI，来自 github.com/cli/cli 的 release）。"
    warn "安装时会弹 UAC 提权窗口，请点「是」。"
    if confirm "现在开始安装？"; then
      winget.exe install --id GitHub.cli -e --source winget \
        --accept-source-agreements --accept-package-agreements \
        || warn "winget 返回了非 0 退出码；若没装成功，按下面的手动方式重来一次。"
    else
      DO_INSTALL=2
    fi
  else
    warn "这台机器上没有 winget。"
    DO_INSTALL=2
  fi
fi

if [[ "$DO_INSTALL" == "2" ]]; then
  open_url "https://cli.github.com/"
  step "点「Download for Windows」，下载 .msi 安装包"
  step "双击 .msi，按提示 Next → Install（同样会弹 UAC）"
  pause "装完了按 Enter 继续"
fi

GH_EXE=$(find_gh || true)

# ── 2/5 验证 + PATH 说明 ──────────────────────────────────────────────────
stage "验证安装（以及 PATH 说明）"
if [[ -z "$GH_EXE" ]]; then
  warn "没找到 gh.exe（找过 /c/Program Files/GitHub CLI/ 和 PATH）。"
  say "说明上一步的安装没有真正完成 —— 重跑本向导第 1 步即可。"
  SKIPPED+=("确认 gh 已安装（gh --version）")
else
  say "用绝对路径验证："
  "$GH_EXE" --version || warn "gh --version 执行失败"
  note "路径：$GH_EXE"
  say "以后在新开的 PowerShell / CMD 窗口里，直接敲 gh 就行。"
  note "当前这个窗口的 PATH 是打开时的快照，所以这里用绝对路径。"
fi
pause "按 Enter 继续"

# ── 3/5 登录（设备码授权） ────────────────────────────────────────────────
stage "登录 GitHub（设备码授权）"
if [[ -z "$GH_EXE" ]]; then
  warn "没有可用的 gh，跳过登录。"
  SKIPPED+=("gh 登录（手动执行：gh auth login --web）")
else
  say "接下来 gh 会打印一次性代码，长这样（代码同时会自动进你的剪贴板）："
  note "    ! One-time code (XXXX-XXXX) copied to clipboard"
  note "    Open this URL to continue in your web browser: https://github.com/login/device"
  step "把代码粘进授权页（Ctrl+V 就行），点 Continue → Authorize github"
  step "授权期间别关这个窗口，gh 会自己继续；代码约 15 分钟内有效。"

  # gh 不读 Windows 系统代理：这里把系统代理补成环境变量，否则会直连超时。
  if [[ -z "${HTTPS_PROXY:-}" && -z "${https_proxy:-}" ]]; then
    sysprox=$(system_proxy || true)
    if [[ -n "$sysprox" ]]; then
      pen=${sysprox%%|*}
      srv=${sysprox#*|}
      srv=${srv%%;*}
      if [[ "$srv" == *=* ]]; then srv=${srv#*=}; fi          # 形如 https=host:port
      srv=${srv#*://}
      if [[ "$pen" == "1" && -n "$srv" ]]; then
        phost=${srv%%:*}; pport=${srv##*:}
        if (exec 3<>/dev/tcp/"$phost"/"$pport") 2>/dev/null; then
          export HTTPS_PROXY="http://$srv" HTTP_PROXY="http://$srv"
          say "检测到系统代理 $srv 正在监听 —— 已临时为 gh 启用（gh 不读 Windows 系统代理设置）。"
        else
          warn "系统代理指向 $srv，但那个端口现在没在监听。"
          warn "请先启动你的代理客户端，否则 gh 连不上 github.com（device code 都发不出去）。"
          pause "代理已启动后按 Enter 继续"
        fi
      fi
    fi
  else
    say "已检测到 HTTPS_PROXY 环境变量，gh 会走它。"
  fi

  open_url "https://github.com/login/device"
  pause "准备好后按 Enter，把终端交给 gh"
  if ! "$GH_EXE" auth login --hostname github.com --git-protocol https --web; then
    warn "gh auth login 没走完。"
    say "  若报 'connection failed / wsarecv / dial tcp ... github.com' —— 那是代理没生效："
    say "  先启动代理客户端，然后在同一个窗口里执行："
    note "    export HTTPS_PROXY=http://127.0.0.1:7897 HTTP_PROXY=http://127.0.0.1:7897"
    note "    gh auth login --hostname github.com --git-protocol https --web"
    SKIPPED+=("gh 登录（gh auth login --hostname github.com --git-protocol https --web）")
  fi
  if "$GH_EXE" auth status >/dev/null 2>&1; then
    say "登录成功 ✅"
  else
    warn "gh auth status 仍未通过。"
    SKIPPED+=("gh 登录（gh auth login --hostname github.com --git-protocol https --web）")
  fi
fi
pause "按 Enter 继续"

# ── 4/5 git 凭据（可选） ──────────────────────────────────────────────────
stage "让 git 也用 gh 的凭据（可选）"
say "配置后 git clone / push 私有仓库会直接用 gh 登录的账号，不用再配 PAT。"
if [[ -z "$GH_EXE" ]]; then
  warn "没有可用的 gh，跳过。"
  SKIPPED+=("gh auth setup-git")
elif confirm "执行 gh auth setup-git 吗？"; then
  if "$GH_EXE" auth setup-git; then
    say "已配置。当前 git 全局的 credential 项："
    git config --global --get-regexp '^credential' || note "（暂时没有 credential.* 项，属正常）"
  else
    warn "setup-git 失败，可稍后手动执行：gh auth setup-git"
    SKIPPED+=("gh auth setup-git")
  fi
else
  note "跳过。以后想做：gh auth setup-git"
  SKIPPED+=("gh auth setup-git（你选择跳过）")
fi
pause "按 Enter 继续"

# ── 5/5 自检 + 收尾 ───────────────────────────────────────────────────────
stage "最后的自检"
if [[ -n "$GH_EXE" ]]; then
  say "登录状态："
  "$GH_EXE" auth status || warn "gh auth status 没通过（没登录或网络问题）"
else
  warn "gh 目前不可用，收尾清单里会列出要补做的事。"
fi

finish

printf '\n%s%s  接下来怎么用 gh%s\n' "$BOLD" "$BLUE" "$RESET"
note "gh auth status        看登录状态"
note "gh repo list           列出你的仓库（加 --limit 100 多看几个）"
note "gh pr create           从当前分支开 PR"
note "gh issue list          看 issue"
note "gh --help              全部命令；手册见 https://cli.github.com/manual/"
printf '\n'
note "卸载：winget uninstall --id GitHub.cli -e"
note "装完第一次用建议新开一个终端窗口，让 PATH 生效。"

# 代理提醒：gh（Go）和 git（libcurl）都不读 Windows 的 WinINET 系统代理设置，
# 而浏览器和 PowerShell 读 —— 所以「浏览器能上 GitHub」并不代表 gh 能上。
psrv=$(system_proxy || true)
psrv=${psrv#*|}
psrv=${psrv%%;*}
psrv=${psrv#*=}
psrv=${psrv#*://}
if [[ -n "$psrv" ]]; then
  printf '\n'
  warn "这台机器有系统代理 $psrv，但 gh / git 不读它，新终端里要自己带："
  note "  临时（当前窗口）：\$env:HTTPS_PROXY='http://$psrv'   # PowerShell"
  note "  永久（新开窗口也生效）：setx HTTPS_PROXY http://$psrv"
  note "  git 单独配（只对 GitHub 生效，不影响国内 git 服务）："
  note "    git config --global http.https://github.com/.proxy http://$psrv"
  note "  提醒：永久设 HTTPS_PROXY 后，代理客户端没开时其它命令行工具也会连不上。"
fi
printf '\n'
